package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeDeserializerBase._findDeserializer
 */
public class TypeDeserializerBase__findDeserializer_TriageGen1Test {

    private DeserializationContext ctxt;
    private TypeIdResolver idResolver;
    private BeanProperty property;
    private JsonDeserializer<Object> mockDeserializer;
    private Map<String, JsonDeserializer<Object>> deserializers;
    private TestTypeDeserializer testInstance;

    // Concrete implementation to test protected method
    private static class TestTypeDeserializer extends TypeDeserializerBase {
        protected TestTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                      boolean typeIdVisible, Class<?> defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(BeanProperty prop) { return null; }
        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override
        public String baseTypeName() { return "test"; }

        // Expose the protected method for testing
        @Override
        public JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return super._findDeserializer(ctxt, typeId);
        }

        // Mocking the internal state for the purpose of the test via reflection or accessor if possible.
        // Since we can't easily inject into private fields of the base class without reflection, 
        // we use a subclass and assume we can manipulate the state or use a spy.
        // However, for this exercise, I will simulate the field access via a spy/subclass approach.

        public void setDeserializers(Map<String, JsonDeserializer<Object>> map) {
            try {
                java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_deserializers");
                field.setAccessible(true);
                field.set(this, map);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        public void setBaseType(JavaType baseType) {
            try {
                java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_baseType");
                field.setAccessible(true);
                field.set(this, baseType);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        public void setProperty(BeanProperty property) {
            try {
                java.lang.reflect.Field field = TypeDeserializerBase.class.getDeclaredField("_property");
                field.setAccessible(true);
                field.set(this, property);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        idResolver = mock(TypeIdResolver.class);
        property = mock(BeanProperty.class);
        mockDeserializer = mock(JsonDeserializer.class);
        deserializers = new HashMap<>();

        testInstance = spy(new TestTypeDeserializer(null, idResolver, "type", true, Object.class));
        testInstance.setDeserializers(deserializers);
        testInstance.setProperty(property);
    }

    @Test
    public void testFindDeserializer_AlreadyExists() throws IOException {
        String typeId = "existing";
        deserializers.put(typeId, mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertSame(mockDeserializer, result);
        verifyNoInteractions(idResolver, ctxt);
    }

    @Test
    public void testFindDeserializer_TypeNotFound_DefaultImplFound() throws IOException {
        String typeId = "unknown";
        JavaType nullType = null;

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(nullType);
        doReturn(mockDeserializer).when(testInstance)._findDefaultImplDeserializer(ctxt);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertSame(mockDeserializer, result);
        assertEquals(mockDeserializer, deserializers.get(typeId));
        verify(idResolver).typeFromId(ctxt, typeId);
    }

    @Test
    public void testFindDeserializer_TypeNotFound_HandleUnknown() throws IOException {
        String typeId = "unknown";
        JavaType nullType = null;

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(nullType);
        doReturn(null).when(testInstance)._findDefaultImplDeserializer(ctxt);
        doReturn(mockDeserializer).when(testInstance)._handleUnknownTypeId(eq(ctxt), eq(typeId), eq(idResolver), any());

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertSame(mockDeserializer, result);
        verify(testInstance)._handleUnknownTypeId(eq(ctxt), eq(typeId), eq(idResolver), any());
    }

    @Test
    public void testFindDeserializer_TypeFound_WithNarrowing() throws IOException {
        String typeId = "myType";
        JavaType baseType = mock(JavaType.class);
        JavaType foundType = mock(JavaType.class);
        JavaType narrowedType = mock(JavaType.class);

        testInstance.setBaseType(baseType);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(foundType);
        when(foundType.getRawClass()).thenReturn(String.class);
        // Simulate matching class type check
        when(baseType.getClass()).thenReturn(foundType.getClass()); 
        when(baseType.narrowBy(String.class)).thenReturn(narrowedType);
        when(ctxt.findContextualValueDeserializer(narrowedType, property)).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertSame(mockDeserializer, result);
        verify(baseType).narrowBy(String.class);
        verify(ctxt).findContextualValueDeserializer(narrowedType, property);
    }

    @Test
    public void testFindDeserializer_TypeFound_NoNarrowing() throws IOException {
        String typeId = "myType";
        JavaType baseType = mock(JavaType.class);
        JavaType foundType = mock(JavaType.class);

        testInstance.setBaseType(baseType);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(foundType);
        // Different class to skip narrowing if-block
        when(baseType.getClass()).thenReturn(Object.class); 
        when(ctxt.findContextualValueDeserializer(foundType, property)).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertSame(mockDeserializer, result);
        verify(baseType, never()).narrowBy(any());
        verify(ctxt).findContextualValueDeserializer(foundType, property);
    }

    @Test
    public void testFindDeserializer_TypeFound_NoBaseType() throws IOException {
        String typeId = "myType";
        JavaType foundType = mock(JavaType.class);

        testInstance.setBaseType(null);
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(foundType);
        when(ctxt.findContextualValueDeserializer(foundType, property)).thenReturn(mockDeserializer);

        JsonDeserializer<Object> result = testInstance._findDeserializer(ctxt, typeId);

        assertSame(mockDeserializer, result);
        verify(ctxt).findContextualValueDeserializer(foundType, property);
    }
}
